create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_path text,timezone text default 'Europe/London',theme text default 'forest',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.health_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,metric_key text not null,value numeric not null,logged_at timestamptz not null default now(),context text,deleted_at timestamptz);
create table if not exists public.habits(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,tracking_type text,target_mode text,target_value numeric,target_min numeric,target_max numeric,unit text,deleted_at timestamptz);
create table if not exists public.habit_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,habit_id uuid references public.habits(id),log_date date,value numeric,completed boolean,achievement_ratio numeric,is_personal_best boolean default false,deleted_at timestamptz);
create table if not exists public.workout_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text,started_at timestamptz,ended_at timestamptz,status text,active_calories numeric,average_heart_rate numeric,rpe numeric,image_path text,deleted_at timestamptz);
create table if not exists public.fasting_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,started_at timestamptz,ended_at timestamptz,target_hours numeric,status text,estimated_effective_hours numeric,deleted_at timestamptz);
create table if not exists public.gratitude_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,entry_date date,body text,image_path text,deleted_at timestamptz);
create table if not exists public.dashboard_layouts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,viewport text,widgets jsonb,theme text,unique(user_id,viewport));
do $$declare t text;begin foreach t in array array['profiles','health_logs','habits','habit_logs','workout_sessions','fasting_sessions','gratitude_entries','dashboard_layouts'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
